   136  int fr_tacacs_body_xor(fr_tacacs_packet_t const *pkt, uint8_t *body, size_t body_len, char const *secret, size_t secret_len)
   137  {
   138          uint8_t pad[MD5_DIGEST_LENGTH];
   139          uint8_t *buf;
   140          int pad_offset;
   141
   142          if (!secret) {
   143                  if (pkt->hdr.flags & FR_TAC_PLUS_UNENCRYPTED_FLAG)
   144                          return 0;
   145                  else {
   146                          fr_strerror_const("Packet is encrypted but no secret for the client is set");
   147                          return -1;
   148                  }
   149          }
   150
   151          if (pkt->hdr.flags & FR_TAC_PLUS_UNENCRYPTED_FLAG) {
   152                  fr_strerror_const("Packet is unencrypted but a secret has been set for the client");
   153                  return -1;
   154          }
   155
   156          pad_offset = sizeof(pkt->hdr.session_id) + secret_len + sizeof(pkt->hdr.version) + sizeof(pkt->hdr.seq_no);
   157
   158          /* MD5_1 = MD5{session_id, key, version, seq_no} */
   159          /* MD5_n = MD5{session_id, key, version, seq_no, MD5_n-1} */
   160          buf = talloc_array(NULL, uint8_t, pad_offset + MD5_DIGEST_LENGTH);
   161
   162          memcpy(&buf[0], &pkt->hdr.session_id, sizeof(pkt->hdr.session_id));
   163          memcpy(&buf[sizeof(pkt->hdr.session_id)], secret, secret_len);
   164          memcpy(&buf[sizeof(pkt->hdr.session_id) + secret_len], &pkt->hdr.version, sizeof(pkt->hdr.version));
   165          memcpy(&buf[sizeof(pkt->hdr.session_id) + secret_len + sizeof(pkt->hdr.version)], &pkt->hdr.seq_no, sizeof(pkt->hdr.seq_no));
   166
   167          fr_md5_calc(pad, buf, pad_offset);
   168
   169          size_t pos = 0;
   170          do {
   171                  for (size_t i = 0; i < MD5_DIGEST_LENGTH && pos < body_len; i++, pos++)
   172                          body[pos] ^= pad[i];
   173
   174                  if (pos == body_len)
   175                          break;
   176
   177                  memcpy(&buf[pad_offset], pad, MD5_DIGEST_LENGTH);
   178                  fr_md5_calc(pad, buf, pad_offset + MD5_DIGEST_LENGTH);
   179          } while (1);
   180
   181          talloc_free(buf);
   182
   183          return 0;
   184  }
