   186  /**
   187   *      Return how long a TACACS+ packet is
   188   *
   189   *      Note that we only look at the 12 byte packet header.  We don't
   190   *      (yet) do validation on authentication / authorization /
   191   *      accounting headers.  The packet may still be determined later
   192   *      to be invalid.
   193   *
   194   * @param buffer        to check
   195   * @param buffer_len    length of the buffer
   196   * @return
   197   *      >0              size of the TACACS+ packet.  We want.  MAY be larger than "buffer_len"
   198   *      <=0             error, packet should be discarded.
   199   */
   200  ssize_t fr_tacacs_length(uint8_t const *buffer, size_t buffer_len)
   201  {
   202          fr_tacacs_packet_t const *pkt = (fr_tacacs_packet_t const *) buffer;
   203          size_t length, want;
   204
   205          /*
   206           *      Check that we have a full TACACS+ header before
   207           *      decoding anything.
   208           */
   209          if (buffer_len < sizeof(pkt->hdr)) {
   210                  return sizeof(pkt->hdr);
   211          }
   212
   213          /*
   214           *      TACACS major / minor version MUST be 12.0 or 12.1
   215           */
   216          if (!((buffer[0] == 0xc0) || (buffer[0] == 0xc1))) {
   217                  fr_strerror_printf("Unsupported TACACS+ version %02x", buffer[0]);
   218                  return -1;
   219          }
   220
   221          /*
   222           *      There's no reason to accept 64K TACACS+ packets.
   223           */
   224          if ((buffer[8] != 0) || (buffer[9] != 0)) {
   225                  fr_strerror_const("Packet is too large.  Our limit is 64K");
   226                  return -1;
   227          }
   228
   229          /*
   230           *      There are only 3 types of packets which are supported.
   231           */
   232          if (!((pkt->hdr.type == FR_TAC_PLUS_AUTHEN) ||
   233                (pkt->hdr.type == FR_TAC_PLUS_AUTHOR) ||
   234                (pkt->hdr.type == FR_TAC_PLUS_ACCT))) {
   235                  fr_strerror_printf("Unknown packet type %u", pkt->hdr.type);
   236                  return -1;
   237          }
   238
   239          length = sizeof(pkt->hdr) + ntohl(pkt->hdr.length);
   240
   241          if (buffer_len < length) return length;
   242
   243          /*
   244           *      We want at least the headers for the various packet
   245           *      types.  Note that we do NOT check the lengths in the
   246           *      headers against buffer / buffer_len.  That process is
   247           *      complex and error-prone.  It's best to leave it in one
   248           *      place: fr_tacacs_decode().
   249           */
   250          switch (pkt->hdr.type) {
   251          default:
   252                  fr_assert(0);   /* should have been caught above */
   253                  return -1;
   254
   255          case FR_TAC_PLUS_AUTHEN:
   256                  if (packet_is_authen_start_request(pkt)) {
   257                          want = sizeof(pkt->hdr) + sizeof(pkt->authen.start);
   258
   259                  } else if (packet_is_authen_continue(pkt)) {
   260                          want = sizeof(pkt->hdr) + sizeof(pkt->authen.cont);
   261
   262                  } else {
   263                          fr_assert(packet_is_authen_reply(pkt));
   264                          want = sizeof(pkt->hdr) + sizeof(pkt->authen.reply);
   265                  }
   266                  break;
   267
   268          case FR_TAC_PLUS_AUTHOR:
   269                  if (packet_is_author_request(pkt)) {
   270                          want = sizeof(pkt->hdr) + sizeof(pkt->author.req);
   271                  } else {
   272                          fr_assert(packet_is_author_response(pkt));
   273                          want = sizeof(pkt->hdr) + sizeof(pkt->author.res);
   274                  }
   275                  break;
   276
   277          case FR_TAC_PLUS_ACCT:
   278                  if (packet_is_acct_request(pkt)) {
   279                          want = sizeof(pkt->hdr) + sizeof(pkt->acct.req);
   280                  } else {
   281                          fr_assert(packet_is_acct_reply(pkt));
   282                          want = sizeof(pkt->hdr) + sizeof(pkt->acct.reply);
   283                  }
   284                  break;
   285          }
   286
   287          if (want > length) {
   288                  fr_strerror_printf("Packet is too small.  Want %zu, got %zu", want, length);
   289                  return -1;
   290          }
   291
   292          return length;
   293  }
